// Destructive cases operate only on payloads generated by this test invocation.
// All source fixtures, command reports and interrupted stores remain retained.
import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import {spawnSync} from 'node:child_process';
import {fixture,log,frames,replayId,buildId} from '../fixtures/replay-import-command-fixture.js';
import {fixture as analysisFixture} from '../fixtures/replay-analysis-command-fixture.js';
import {database,logical,hashFiles} from '../fixtures/replay-log-review-command-fixture.js';
import {importSyntheticCache as admit} from '../../tools/replay-import-command-fixture.js';
import {updateSyntheticLogReview,updateSyntheticScoreReview} from '../../tools/replay-log-review-fixture.js';
import {runSyntheticLifecycle as run} from '../../tools/replay-lifecycle-command-fixture.js';
import {completeFixtureLogReview,completeFixtureScoreReview} from '../../tools/replay-score-review-fixture.js';
import {openStore} from '../../tools/replay-store.js';
import {buildSyntheticHistoricalIndex as index,screenSyntheticReplay as screen} from '../../tools/replay-evidence-consumers-fixture.js';
import {analyzeSyntheticReplay} from '../../tools/replay-analysis-command-fixture.js';
import {importCacheFile,importScoreCacheFile,updateReview,updateScoreReview,cleanupScoreSource} from '../../tools/replay-logs.js';
const taskId='codex/lifecycle-cache';
async function make(t,collection='log',options={}){
    const f=await fixture(t),q=f.write('selected_0',collection==='log'?log(options):frames(),{collection,time:collection==='log'?1:2}),r=(await admit(q)).record;
    return {...f,r,k:{collection,replayId,fingerprint:r.fingerprint},q,request:{synthetic:true,root:f.root,replayId,fingerprint:r.fingerprint}};
}
async function review(f,task=taskId){const update=f.k.collection==='log'?updateSyntheticLogReview:updateSyntheticScoreReview;await update({...f.request,taskId:task,action:'claim'});await update({...f.request,taskId:task,action:'examined'});}
async function finish(f){return(f.k.collection==='log'?completeFixtureLogReview:completeFixtureScoreReview)({root:f.root,schemaVersion:1,replayId,fingerprint:f.k.fingerprint,taskId});}
const hist=f=>({synthetic:true,root:f.root,cache:true,selection:{version:1,taskId,matches:[{replayId,logFingerprints:f.k.collection==='log'?[f.k.fingerprint]:[],scoreFingerprints:f.k.collection==='score'?[f.k.fingerprint]:[],opponent:'synthetic',configuration:{label:'synthetic',basis:'generated',expectedBuildId:buildId},reportedFinalTick:1}]}});
for(const collection of ['log','score'])test('end-to-end import review analysis cache and '+collection+' lifecycle',async t=>{
    const f=await make(t,collection);await review(f);const before=logical(f.root);
    const q={synthetic:true,root:f.root,replayId,reportMode:'compact',[collection==='log'?'fingerprints':'scoreFingerprints']:[f.k.fingerprint]};
    assert.ok(await analyzeSyntheticReplay(q));
    const a=await index(hist(f)),b=await index(hist(f));assert.equal(a.matches[0].cache,'miss');assert.equal(b.matches[0].cache,'hit');
    assert.deepEqual(logical(f.root),before);
    if(collection==='score')assert.equal((await run({...f.request,action:'score-verify'})).verified,true);
    const result=await run({...f.request,action:collection==='log'?'done':'score-done',taskId});
    assert.equal(result.recordStatus,'done');
    if(collection==='score'){
        assert.ok(fs.existsSync(path.join(f.root,f.r.outputPath)));const done=logical(f.root);assert.equal((await run({...f.request,action:'score-done',taskId})).changed,false);assert.deepEqual(logical(f.root),done);
        assert.equal((await run({...f.request,action:'score-cleanup'})).kind,'retired');
    }
    assert.equal(f.store.getRecord(f.k).kind,'retired');assert.ok(!fs.existsSync(path.join(f.root,f.r.outputPath)));
    const retired=logical(f.root),again=await run({...f.request,action:collection==='log'?'reconcile':'score-cleanup'});assert.equal(again.changed,false);assert.deepEqual(logical(f.root),retired);
    const missing=await index(hist(f));assert.equal(missing.matches[0].selectedEvidence[0].availability,'retired');
    if(collection==='log')assert.equal(f.store.entityCounts().maps,1);
});
for(const collection of ['log','score'])test(collection+' owners, eligibility, unknown reviews and neutral completion',async t=>{
    const f=await make(t,collection),before=logical(f.root);
    await assert.rejects(run({...f.request,action:collection==='log'?'done':'score-done',taskId}),{code:'NOT_CLAIMED'});assert.deepEqual(logical(f.root),before);
    await review(f);await review(f,'other/owner');
    await f.store.withWriter(w=>w.transaction(tx=>tx.setProperty({owner:{kind:'review',key:JSON.stringify([JSON.stringify([collection,replayId,f.k.fingerprint]),'other/owner'])},pointer:'/extra',ordinal:3,value:[false,null,2]})));
    const result=await run({...f.request,action:collection==='log'?'complete':'score-done',taskId});assert.equal(result.recordStatus,'claim');
    assert.deepEqual(f.store.getReview(f.k,'other/owner').value.extra,[false,null,2]);const stable=logical(f.root);assert.equal((await finish(f)).changed,false);assert.deepEqual(logical(f.root),stable);
});
for(const collection of ['log','score'])for(const boundary of ['retirement-verified','retirement-before-unlink','retirement-after-unlink','retirement-directory-synced','retirement-before-finalize'])test(collection+' interrupted retirement '+boundary,async t=>{
    const f=await make(t,collection);await review(f);await finish(f);let hit=false;
    const s=await openStore({root:f.root,mode:'write',fault:b=>{if(b===boundary&&!hit){hit=true;throw Object.assign(Error('synthetic interruption'),{code:'EIO'});}}});
    try{await assert.rejects(s.withWriter(w=>collection==='log'?w.retireLog(f.k):w.retireScore(f.k)),{code:'EIO'});}finally{s.close();}assert.ok(hit);
    const result=await run({...f.request,action:collection==='log'?'reconcile':'score-cleanup'});assert.equal(result.kind,'retired');assert.equal(f.store.getRecord(f.k).kind,'retired');
});
test('log missing original output allowed, score missing before intent rejects',async t=>{
    for(const collection of ['log','score']){const f=await make(t,collection);await review(f);await finish(f);fs.unlinkSync(path.join(f.root,f.r.outputPath));const before=logical(f.root);
        if(collection==='log')assert.equal((await run({...f.request,action:'reconcile'})).kind,'retired');
        else{await assert.rejects(run({...f.request,action:'score-cleanup'}),{code:'UNAVAILABLE'});assert.deepEqual(logical(f.root),before);}}
});
test('diagnostic-only log retirement keeps map and removes only owned generated payloads',async t=>{
    const f=await make(t,'log',{game:false});await review(f);assert.equal(f.r.outputPath,null);await run({...f.request,action:'done',taskId});assert.equal(f.store.getRecord(f.k).kind,'retired');assert.equal(f.store.entityCounts().maps,1);
});
for(const defect of ['output','review-owner','history','foreign-intent'])test('retirement rejects '+defect+' without repair/deletion',async t=>{
    const f=await make(t);await review(f);await finish(f);
    if(defect==='output')fs.appendFileSync(path.join(f.root,f.r.outputPath),'changed');
    else database(f.root,db=>{if(defect==='review-owner')db.exec("UPDATE reviews SET owner_key='forged'");if(defect==='history')db.prepare("UPDATE properties SET value=? WHERE owner_kind='replay' AND pointer='/retiredFingerprints'").run(JSON.stringify(['f'.repeat(64)]));if(defect==='foreign-intent')db.prepare('INSERT INTO operations VALUES (?,?,?,?,?,?)').run('foreign','log',replayId,f.k.fingerprint,'publish',0);});
    const before=logical(f.root),files=hashFiles(f.root);await assert.rejects(run({...f.request,action:'reconcile'}));assert.deepEqual(logical(f.root),before);assert.deepEqual(hashFiles(f.root),files);
});
test('completion transaction failure rolls back and later resume works',async t=>{
    const f=await make(t);await review(f);const before=logical(f.root),{DatabaseSync}=await import('node:sqlite'),exec=DatabaseSync.prototype.exec;
    DatabaseSync.prototype.exec=function(sql){if(sql==='COMMIT')throw Object.assign(Error('synthetic commit failure'),{code:'EIO'});return exec.call(this,sql);};
    try{await assert.rejects(finish(f),{code:'EIO'});}finally{DatabaseSync.prototype.exec=exec;}assert.deepEqual(logical(f.root),before);await run({...f.request,action:'done',taskId});
});
test('CLI lifecycle uses explicit synthetic selection and fences unsupported commands',async t=>{
    const f=await make(t,'score');await review(f);
    for(const action of ['score-verify','score-done','score-cleanup']){const r=spawnSync(process.execPath,['tools/replay-logs.js','--synthetic-sqlite',f.root,action,replayId,f.k.fingerprint,...(action==='score-done'?[taskId]:[])],{encoding:'utf8',timeout:30000});assert.equal(r.status,0,r.stderr);t.diagnostic(JSON.stringify({action,exit:r.status,result:JSON.parse(r.stdout)}));}
    const before=logical(f.root);for(const action of ['watch','scan','register-local']){const r=spawnSync(process.execPath,['tools/replay-logs.js','--synthetic-sqlite',f.root,action],{encoding:'utf8',timeout:30000});assert.notEqual(r.status,0);}for(const action of ['upgrade-map-checksums','migrate-status']){const r=spawnSync(process.execPath,['tools/replay-logs.js','--synthetic-sqlite',f.root,action],{encoding:'utf8',timeout:30000});assert.equal(r.status,0,r.stderr);}assert.deepEqual(logical(f.root),before);
});
test('cache rechecks claims and payloads on hits, invalidates changed selected metadata',async t=>{
    const f=await make(t);await review(f);const q=hist(f);await index(q);assert.equal((await index(q)).matches[0].cache,'hit');
    await f.store.withWriter(w=>w.transaction(tx=>tx.setProperty({owner:{kind:'record',key:JSON.stringify(['log',replayId,f.k.fingerprint])},pointer:'/extra',ordinal:70,value:'selected change'})));
    assert.equal((await index(q)).matches[0].cache,'miss');
    fs.appendFileSync(path.join(f.root,f.r.outputPath),'corrupt');await assert.rejects(index(q));
});
test('cache cannot hide removed claim or forged report/generation/store identity',async t=>{
    for(const defect of ['claim','report','generation','storeId']){const f=await make(t);await review(f);const q=hist(f);await index(q);const file=path.join(f.root,'analysis_cache',fs.readdirSync(path.join(f.root,'analysis_cache')).find(n=>n.endsWith('.json')));
        if(defect==='claim')database(f.root,db=>db.prepare("UPDATE properties SET value='null' WHERE owner_kind='review' AND pointer='/claimedAt'").run());
        else{const saved=JSON.parse(fs.readFileSync(file));if(defect==='report')saved.report.replayId='forged';if(defect==='generation')saved.generation='9999999';if(defect==='storeId')saved.storeId='foreign';fs.writeFileSync(file,JSON.stringify(saved));}
        const before=logical(f.root);await assert.rejects(index(q),{code:defect==='claim'?'UNCLAIMED':'INVALID_CACHE'});assert.deepEqual(logical(f.root),before);
    }
});
test('unrelated writes do not invalidate selected cache; current generation is rechecked',async t=>{
    const f=await make(t);await review(f);const q=hist(f);await index(q);
    await f.store.withWriter(w=>w.transaction(tx=>tx.setProperty({owner:{kind:'root',key:'root'},pointer:'/unrelated',ordinal:99,value:'unchanged selection'})));
    assert.equal((await index(q)).matches[0].cache,'hit');
});
test('scout opt-in cache retains equivalent report and read-only store state',async t=>{
    const f=await analysisFixture(t,'log','cpu',{transform:d=>{for(const r of d.manifest.records)r.reviews={[taskId]:{claimedAt:'synthetic'}};}});
    const q={synthetic:true,root:f.root,replayId:f.q.replayId,taskId,expectedBuildId:buildId,fingerprints:f.q.fingerprints},before=logical(f.root),a=await screen(q),b=await screen({...q,cache:true}),c=await screen({...q,cache:true});
    assert.deepEqual(a.report,b.report);assert.deepEqual(b.report,c.report);assert.equal(b.cache,'miss');assert.equal(c.cache,'hit');assert.deepEqual(logical(f.root),before);
});
test('unknown schema and unsafe/accessor options reject without mutation',async t=>{
    const f=await make(t,'score'),file=path.join(f.root,'manifest.json'),d=JSON.parse(fs.readFileSync(file));d.schemaVersion=99;fs.writeFileSync(file,JSON.stringify(d));const before=hashFiles(f.root);
    await assert.rejects(run({...f.request,action:'score-cleanup'}),{code:'UNSUPPORTED_STORE'});let hits=0;await assert.rejects(run({...f.request,get action(){hits++;return'score-cleanup';}}),{code:'INVALID_ARGUMENT'});assert.equal(hits,0);assert.deepEqual(hashFiles(f.root),before);
});
for(const collection of ['log','score'])test(collection+' lifecycle matches v2 logical status and retired identity',async t=>{
    const f=await make(t,collection);await(collection==='log'?importCacheFile:importScoreCacheFile)(f.v2,path.join(f.q.sourceRoot,f.q.sourceFile));
    const update=collection==='log'?updateReview:updateScoreReview;
    for(const action of ['claim','examined']){await update(f.v2,action,replayId,f.k.fingerprint,taskId);await(collection==='log'?updateSyntheticLogReview:updateSyntheticScoreReview)({...f.request,taskId,action});}
    const old=await update(f.v2,'done',replayId,f.k.fingerprint,taskId),now=await run({...f.request,action:collection==='log'?'done':'score-done',taskId});assert.equal(now.recordStatus,old.status);
    if(collection==='score'){await cleanupScoreSource(f.v2,replayId,f.k.fingerprint);await run({...f.request,action:'score-cleanup'});}
    const manifest=JSON.parse(fs.readFileSync(path.join(f.v2,'replay_logs','manifest.json')));assert.equal((collection==='log'?manifest.records:manifest.scoreRecords).length,0);
    assert.equal(f.store.getRecord(f.k).kind,'retired');
    if(collection==='log'){const property=f.store.pageProperties({kind:'replay',key:replayId}).rows.find(p=>p.pointer==='/retiredFingerprints');assert.deepEqual(JSON.parse(property.value),manifest.replays[0].retiredFingerprints);}
    else {const rows=f.store.pageProperties({kind:'retired',key:JSON.stringify(['score',replayId,f.k.fingerprint])}).rows;assert.deepEqual(Object.fromEntries(rows.map(p=>[p.pointer.slice(1),JSON.parse(p.value)])),manifest.retiredScoreSources[0]);}
});
test('original log done command resumes an interrupted cleanup intent',async t=>{
    const f=await make(t);await review(f);await finish(f);const s=await openStore({root:f.root,mode:'write',fault:b=>{if(b==='retirement-after-unlink')throw Object.assign(Error('interruption'),{code:'EIO'});}});
    try{await assert.rejects(s.withWriter(w=>w.retireLog(f.k)),{code:'EIO'});}finally{s.close();}
    assert.equal((await run({...f.request,action:'done',taskId})).kind,'retired');
});
test('missing log output presence is journaled exactly across interruption',async t=>{
    const f=await make(t);await review(f);await finish(f);fs.unlinkSync(path.join(f.root,f.r.outputPath));
    const s=await openStore({root:f.root,mode:'write',fault:b=>{if(b==='retirement-directory-synced')throw Object.assign(Error('interruption'),{code:'EIO'});}});
    try{await assert.rejects(s.withWriter(w=>w.retireLog(f.k)),{code:'EIO'});}finally{s.close();}
    const row=logical(f.root).operation_files.find(r=>r.path===f.r.outputPath);assert.equal(row.original_present,0);assert.equal((await run({...f.request,action:'reconcile'})).kind,'retired');
});
for(const collection of ['log','score'])test(collection+' concurrent retirement publishes one tombstone',async t=>{
    const f=await make(t,collection);await review(f);await finish(f);const result=await Promise.all([run({...f.request,action:collection==='log'?'reconcile':'score-cleanup'}),run({...f.request,action:collection==='log'?'reconcile':'score-cleanup'})]);
    assert.deepEqual(result.map(r=>r.kind).sort(),['already-retired','retired']);assert.equal(f.store.entityCounts().retired,1);
});
test('retirement preserves read EIO with close ENOSPC and performs no deletion',async t=>{
    const f=await make(t);await review(f);await finish(f);const before=logical(f.root),files=hashFiles(f.root),target=path.join(f.root,f.r.outputPath),open=fs.openSync,read=fs.readSync,close=fs.closeSync;let selectedFd;
    fs.openSync=(p,...args)=>{const fd=open(p,...args);if(p===target)selectedFd=fd;return fd;};fs.readSync=(fd,...args)=>{if(fd===selectedFd)throw Object.assign(Error('synthetic read'),{code:'EIO'});return read(fd,...args);};fs.closeSync=fd=>{close(fd);if(fd===selectedFd){selectedFd=undefined;throw Object.assign(Error('synthetic close'),{code:'ENOSPC'});}};
    try{await assert.rejects(run({...f.request,action:'reconcile'}),e=>e.code==='EIO'&&e.cleanupFailures?.some(f=>f.systemCode==='ENOSPC'));}finally{fs.openSync=open;fs.readSync=read;fs.closeSync=close;}
    assert.deepEqual(logical(f.root),before);assert.deepEqual(hashFiles(f.root),files);
});
test('cache refuses unsafe symlink directory and retains interrupted publication',async t=>{
    const f=await make(t);await review(f);fs.symlinkSync(f.sourceRoot,path.join(f.root,'analysis_cache'));const before=logical(f.root);await assert.rejects(index(hist(f)));assert.deepEqual(logical(f.root),before);
    const g=await make(t);await review(g);const link=fs.linkSync;let hit=false;fs.linkSync=(a,b)=>{if(String(a).includes('/analysis_cache/.cache-')){hit=true;throw Object.assign(Error('cache interruption'),{code:'EIO'});}return link(a,b);};
    try{await assert.rejects(index(hist(g)),{code:'EIO'});}finally{fs.linkSync=link;}assert.ok(hit);assert.ok(fs.readdirSync(path.join(g.root,'analysis_cache')).some(n=>n.endsWith('.tmp')));assert.equal((await index(hist(g))).matches[0].cache,'miss');
});
test('log history beyond the supported inline capacity rejects before deletion',async t=>{
    const f=await make(t);await review(f);await finish(f);const values=Array.from({length:128},(_,i)=>i.toString(16).padStart(64,'0'));
    const p=f.store.pageProperties({kind:'replay',key:replayId}).rows.find(p=>p.pointer==='/retiredFingerprints');
    await f.store.withWriter(w=>w.transaction(tx=>{for(const [ordinal,fingerprint]of values.entries())tx.insertEntity({kind:'retired',key:JSON.stringify(['log',replayId,fingerprint]),ordinal,value:{}});tx.setProperty({owner:{kind:'replay',key:replayId},pointer:'/retiredFingerprints',ordinal:p.ordinal,value:values});}));
    const before=logical(f.root),files=hashFiles(f.root);await assert.rejects(run({...f.request,action:'reconcile'}),{code:'RESOURCE_LIMIT'});assert.deepEqual(logical(f.root),before);assert.deepEqual(hashFiles(f.root),files);
});
test('directory-sync failure keeps EIO and close ENOSPC and remains resumable',async t=>{
    const f=await make(t);await review(f);await finish(f);const target=path.join(f.root,f.r.outputPath),unlink=fs.unlinkSync,open=fs.openSync,sync=fs.fsyncSync,close=fs.closeSync;let deleted=false,selectedFd,hit=false;
    fs.unlinkSync=p=>{unlink(p);if(p===target)deleted=true;};fs.openSync=(p,...args)=>{const fd=open(p,...args);if(deleted&&p===f.root&&!hit)selectedFd=fd;return fd;};fs.fsyncSync=fd=>{if(fd===selectedFd){hit=true;throw Object.assign(Error('sync'),{code:'EIO'});}return sync(fd);};fs.closeSync=fd=>{close(fd);if(fd===selectedFd){selectedFd=undefined;throw Object.assign(Error('close'),{code:'ENOSPC'});}};
    try{await assert.rejects(run({...f.request,action:'reconcile'}),e=>e.code==='EIO'&&e.cleanupFailures?.some(f=>f.systemCode==='ENOSPC'));}finally{fs.unlinkSync=unlink;fs.openSync=open;fs.fsyncSync=sync;fs.closeSync=close;}
    assert.ok(hit);assert.equal((await run({...f.request,action:'reconcile'})).kind,'retired');
});
test('cache CLI flags connect both derived consumers without changing evidence',async t=>{
    const f=await analysisFixture(t,'log','cpu',{transform:d=>{for(const r of d.manifest.records)r.reviews={[taskId]:{claimedAt:'synthetic'}};}}),before=logical(f.root),selection={version:1,taskId,matches:[{replayId:f.q.replayId,logFingerprints:f.q.fingerprints,opponent:'synthetic',configuration:{label:'synthetic',basis:'generated',expectedBuildId:buildId},reportedFinalTick:8}]},file=path.join(f.root,'selected.json');fs.writeFileSync(file,JSON.stringify(selection));
    for(const tool of ['historical-index','scout-hold-screen'])for(const expected of ['miss','hit']){
        const args=[`tools/${tool}.js`,'--synthetic-sqlite',f.root,...(tool==='historical-index'?[file]:[f.q.replayId,taskId,buildId,...f.q.fingerprints]),'--cache'];
        const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:30000});assert.equal(r.status,0,r.stderr);if(tool==='historical-index')assert.equal(JSON.parse(r.stdout).matches[0].cache,expected);else assert.match(r.stderr,new RegExp(`scout-hold cache: ${expected}`));t.diagnostic(JSON.stringify({command:[process.execPath,...args],exit:r.status,cache:expected}));
    }assert.deepEqual(logical(f.root),before);
});
